CREATE OR REPLACE FUNCTION get_decrypted_lightspeed_integration(p_shop_id UUID) RETURNS TABLE(id UUID, shop_id UUID, integration_type TEXT, access_token TEXT, refresh_token TEXT, expires_at TIMESTAMPTZ, account_id TEXT, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ) SECURITY DEFINER SET search_path = '' LANGUAGE plpgsql AS $$ DECLARE v_key TEXT; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF NOT EXISTS (SELECT 1 FROM public.user_shop_memberships AS usm WHERE usm.user_id = auth.uid() AND usm.shop_id = p_shop_id) THEN RAISE EXCEPTION 'User is not a member of shop %', p_shop_id; END IF; v_key := public.get_lightspeed_encryption_key(); RETURN QUERY SELECT li.id, li.shop_id, li.integration_type, extensions.pgp_sym_decrypt(li.access_token_encrypted, v_key)::TEXT, CASE WHEN li.refresh_token_encrypted IS NOT NULL THEN extensions.pgp_sym_decrypt(li.refresh_token_encrypted, v_key)::TEXT ELSE NULL END, li.expires_at, li.account_id, li.created_at, li.updated_at FROM public.lightspeed_integrations li WHERE li.shop_id = p_shop_id AND li.integration_type = 'lightspeed'; END; $$;

CREATE OR REPLACE FUNCTION upsert_lightspeed_integration(p_shop_id UUID, p_access_token TEXT, p_refresh_token TEXT, p_expires_at TIMESTAMPTZ, p_account_id TEXT) RETURNS VOID SECURITY DEFINER SET search_path = '' LANGUAGE plpgsql AS $$ DECLARE v_key TEXT; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF NOT EXISTS (SELECT 1 FROM public.user_shop_memberships AS usm WHERE usm.user_id = auth.uid() AND usm.shop_id = p_shop_id) THEN RAISE EXCEPTION 'User is not a member of shop %', p_shop_id; END IF; v_key := public.get_lightspeed_encryption_key(); INSERT INTO public.lightspeed_integrations (shop_id, integration_type, access_token_encrypted, refresh_token_encrypted, expires_at, account_id) VALUES (p_shop_id, 'lightspeed', extensions.pgp_sym_encrypt(p_access_token, v_key), CASE WHEN p_refresh_token IS NOT NULL THEN extensions.pgp_sym_encrypt(p_refresh_token, v_key) ELSE NULL END, p_expires_at, p_account_id) ON CONFLICT (shop_id, integration_type) DO UPDATE SET access_token_encrypted = EXCLUDED.access_token_encrypted, refresh_token_encrypted = EXCLUDED.refresh_token_encrypted, expires_at = EXCLUDED.expires_at, account_id = EXCLUDED.account_id; END; $$;
